<script setup>
import { Head,router } from '@inertiajs/vue3'; import AdminLayout from '../../Layouts/AdminLayout.vue'; import Pagination from '../../Components/Pagination.vue';import Icon from '../../Components/Icon.vue'; defineProps({configured:Boolean,config:Object,counts:Object,logs:Object}); const test=()=>router.post('/admin/merchant/test'); const sync=()=>router.post('/admin/merchant/sync-all'); const badge=s=>s==='success'?'bg-emerald-100 text-emerald-700':s==='failed'?'bg-red-100 text-red-700':'bg-amber-100 text-amber-700';
</script><template><AdminLayout><Head title="Google Merchant"/><div class="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p class="section-kicker">Product distribution</p><h1 class="section-title">Google Merchant Center</h1><p class="mt-2 max-w-2xl text-sm text-slate-500">Synchronize active products with Google Merchant.</p></div><div class="flex gap-2"><button class="btn-light" @click="test">Test connection</button><button class="btn-primary" :disabled="!configured" @click="sync">Sync all eligible</button></div></div><div :class="['mt-6 rounded-[10px] border p-5',configured?'border-emerald-200 bg-emerald-50':'border-amber-200 bg-amber-50']"><div class="flex items-start gap-3"><div :class="['mt-0.5 flex h-8 w-8 items-center justify-center rounded-[10px] text-white',configured?'bg-emerald-600':'bg-amber-600']"><Icon :name="configured ? 'tick-circle' : 'warning-2'" :size="18" /></div><div><h2 class="font-black">{{configured?'Integration configured':'Configuration required'}}</h2><p class="mt-1 text-sm leading-6" :class="configured?'text-emerald-700':'text-amber-800'">{{configured?'The service-account file and Merchant account settings were detected.':'Merchant settings are incomplete.'}}</p></div></div></div>
<div class="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div class="card p-5"><p class="text-xs font-bold uppercase text-slate-400">Eligible products</p><b class="mt-2 block text-3xl">{{counts.eligible}}</b></div><div class="card p-5"><p class="text-xs font-bold uppercase text-slate-400">Synced</p><b class="mt-2 block text-3xl text-emerald-600">{{counts.synced}}</b></div><div class="card p-5"><p class="text-xs font-bold uppercase text-slate-400">Pending</p><b class="mt-2 block text-3xl text-amber-600">{{counts.pending}}</b></div><div class="card p-5"><p class="text-xs font-bold uppercase text-slate-400">Failed</p><b class="mt-2 block text-3xl text-red-600">{{counts.failed}}</b></div></div>
<div class="mt-6 grid gap-6 xl:grid-cols-[1fr_360px]"><section class="card overflow-hidden"><div class="border-b p-5"><h2 class="font-black">Synchronization log</h2></div><div class="overflow-x-auto"><table class="admin-table"><thead><tr><th>Product</th><th>Action</th><th>Status</th><th>Date</th><th>Error</th></tr></thead><tbody><tr v-for="log in logs.data" :key="log.id"><td class="font-bold">{{log.product?.name||'Connection test'}}</td><td>{{log.action}}</td><td><span :class="['status',badge(log.status)]">{{log.status}}</span></td><td>{{new Date(log.created_at).toLocaleString()}}</td><td><p class="max-w-64 truncate text-xs text-red-600" :title="log.error_message">{{log.error_message||'—'}}</p></td></tr><tr v-if="!logs.data.length"><td colspan="5" class="py-16 text-center text-slate-400">No synchronization activity.</td></tr></tbody></table></div><div class="p-4"><Pagination :links="logs.links"/></div></section><aside class="space-y-5"><section class="card p-5"><h2 class="font-black">Current settings</h2><dl class="mt-4 space-y-3 text-sm"><div class="flex justify-between gap-3"><dt class="text-slate-500">Enabled</dt><dd class="font-bold">{{config.enabled?'Yes':'No'}}</dd></div><div class="flex justify-between gap-3"><dt class="text-slate-500">Account ID</dt><dd class="font-bold">{{config.account_id||'Not set'}}</dd></div><div class="flex justify-between gap-3"><dt class="text-slate-500">Data source</dt><dd class="font-bold">{{config.data_source_id||'Not set'}}</dd></div><div class="flex justify-between gap-3"><dt class="text-slate-500">Language</dt><dd class="font-bold">{{config.content_language}}</dd></div><div class="flex justify-between gap-3"><dt class="text-slate-500">Feed label</dt><dd class="font-bold">{{config.feed_label}}</dd></div><div class="flex justify-between gap-3"><dt class="text-slate-500">Currency</dt><dd class="font-bold">{{config.currency}}</dd></div></dl></section><section class="rounded-[10px] bg-slate-950 p-5 text-white"><h2 class="font-black">Automated refresh</h2><p class="mt-2 text-sm leading-6 text-slate-300">Scheduled synchronization status.</p><code class="mt-4 block rounded-[8px] bg-black/40 p-3 text-xs text-prinx-300">php artisan schedule:work<br>php artisan queue:work</code></section><section class="card p-5"><h2 class="font-black">Fallback XML feed</h2><p class="mt-2 text-sm text-slate-500">XML product feed.</p><a href="/google-merchant-feed.xml" target="_blank" class="btn-light mt-4 w-full">Open product feed</a></section></aside></div></AdminLayout></template>
